    const canvas = document.getElementById("game-canvas");
    if (!canvas) {
      throw new Error("Could not find #game-canvas element");
    }
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      throw new Error("Could not get 2D rendering context");
    }
